import { Picture, Card, Button } from "march/ui"

// bir kartpostal: ön yüzde resim, basınca arka yüzde hazır bir düğüm; ikisi de aynı Picture yuvasından geçer
const front = { src: "/media/dusk.jpg", alt: "Gün batımında tepeler", width: 1200, height: 800 }

export function Postcard() {
  let $back = false
  const back = <div sx={{ flex: "col", gap: 2, p: 6 }}><strong>Sevgili Deniz,</strong><span>Tepelerde gün batımı harikaydı. Yakında görüşürüz!</span></div>
  return <Card title="Kartpostal" m:theme={$back ? "night" : undefined}>
    <div sx={{ flex: "col", gap: 3 }}>
      {() => <Picture source={$back ? back as Node : front} fit="cover" />}
      <Button size="sm" on:click={() => $back = !$back}>{() => ($back ? "Ön yüzü göster" : "Arkasını çevir")}</Button>
    </div>
  </Card>
}

import { Picture, Card, Badge } from "march/ui"

// bir blog yazısının kapağı: ilk ekranda olduğu için hemen yüklenir (eager), boyutu bilindiğinden sayfa kaymaz;
// resim gelmezse yerinde bir yedek metin
const posts = [
  { title: "Sinyallerle tanışın", cover: { src: "/media/dusk.jpg", alt: "Gün batımı", width: 1200, height: 800 } },
  { title: "Kayıp kapak", cover: { src: "/media/kayip-kapak.jpg", alt: "Kapak", width: 1200, height: 800 } },
]

export function ArticleCover() {
  let $loaded = 0
  return <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
    {posts.map((p, i) => <Card title={p.title}>
      <Picture source={p.cover} loading={i === 0 ? "eager" : "lazy"} fit="cover" fallback="Kapak yüklenemedi" onLoad={() => $loaded++} />
      <div sx={{ mt: 2 }}><Badge tone={i === 0 ? "success" : "neutral"}>{i === 0 ? "Öne çıkan" : "Arşiv"}</Badge></div>
    </Card>)}
    <span sx={{ color: "muted", text: "sm" }}>Yüklenen kapak: {() => $loaded}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PictureLab } from "./PictureLab.tsx"

// PictureLab'in testleri: kaydedince Testler sekmesinde çalışır
test("nesne bir img olur: tembel, eşzamansız çözülen, boyutlu", () => {
  const s = renderTest(() => <PictureLab />)
  const img = s.get(".lab-object")
  expect(img?.tagName).toBe("IMG")
  expect(img?.getAttribute("loading")).toBe("lazy")
  expect(img?.getAttribute("decoding")).toBe("async")
  expect(img?.getAttribute("width")).toBe("1200")
})

test("loading=eager: lazy yok, yüksek öncelik; ek öznitelikler img'ye geçer", () => {
  const s = renderTest(() => <PictureLab />)
  const img = s.get(".lab-eager")
  expect(img?.hasAttribute("loading")).toBe(false)
  expect(img?.getAttribute("fetchpriority")).toBe("high")
  expect(img?.getAttribute("data-kind")).toBe("hero")
  expect(img?.classList.contains("m-picture-contain")).toBe(true)
})

test("srcset ve sizes yazılır; hazır düğüm olduğu gibi çizilir", () => {
  const s = renderTest(() => <PictureLab />)
  expect(s.get(".lab-srcset")?.getAttribute("sizes")).toBe("(max-width: 600px) 100vw, 300px")
  expect(s.get(".lab-node")).not.toBe(null)
  expect(s.sees("Kendi düğümüm")).toBe(true)
})
